$f = Join-Path ([IO.Path]::GetTempPath()) "strands-web-fetch-$([guid]::NewGuid())"
$s = 127
try {
  curl.exe -sSL -g --fail --proto '=http,https' --proto-redir '=http,https' --max-time 30 -A 'strands-harness/1.0' -o $f --stderr "$f.err" -w '%{content_type}\n%{url_effective}\n' 'https://example.com/it''s'
  $s = $LASTEXITCODE
  if ($s -eq 0) {
    $in = [IO.File]::OpenRead($f)
    try { $b = (New-Object IO.BinaryReader $in).ReadBytes([Math]::Min($in.Length, 5242880)) } finally { $in.Dispose() }
    [Convert]::ToBase64String($b)
  } elseif (Test-Path -LiteralPath "$f.err") { [Console]::Error.Write([IO.File]::ReadAllText("$f.err")) }
} catch { if ($s -eq 0) { $s = 1 }; [Console]::Error.Write($_.Exception.Message) }
Remove-Item -Force -LiteralPath $f, "$f.err" -ErrorAction SilentlyContinue
exit $s
